A:  Grouping 2

  The maximum number of groups consisting of three or more students is ⌊N/3⌋.
  So,you can get 100 points by print ⌊N/3⌋.

#include <cstdio >
int N;
int main ()
{
         scanf ("%d",&N);
         printf ("%d\n",N/3);
}



B:  Hina Arare

   It is guaranteed that there are pink,white,green arare,so it is possible to distinguish the number
of colors by the existence of yellow arare.
  So, you can get 200 points by print ‘Four‘ when yellow arare exists, ‘Three‘ otherwise.

#include <cstdio >
int N;
char c;
int main ()
{
         scanf ("%d",&N);
         bool flag=false;
        for(int i=0;i<N;i++)
          {
                 scanf ("%c",&c);
                if(c==’Y’) flag=true;
          }
        if(flag)puts (" Four ");
         else puts (" Three ");
}





